//! Compile-and-load infrastructure for natively compiled spec functions.
//!
//! Takes Rust source code generated by `native_codegen::generate_eval_function`,
//! compiles it to a cdylib via `rustc`, and loads the resulting shared library
//! via `libloading`. Compiled functions are cached by expression pointer + env
//! names (matching `BytecodeCache`'s strategy).

use crate::error::{TranspileError, TranspileResult};
use crate::modelcheck::value::{RuntimeResult, RuntimeValue};
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::{Arc, Mutex};

/// Function signature for natively compiled eval functions.
type NativeEvalFn = unsafe fn(&[RuntimeValue]) -> RuntimeResult<RuntimeValue>;

/// Cache key: (expression pointer, environment variable names).
type NativeCacheKey = (usize, Vec<String>);

/// Cache map: key → compiled function (None = cached failure).
type NativeCacheMap = HashMap<NativeCacheKey, Option<Arc<NativeFunction>>>;

/// A natively compiled eval function loaded from a cdylib.
///
/// Holds the `libloading::Library` to keep the shared library mapped.
/// The function pointer is valid as long as `_lib` is alive.
pub struct NativeFunction {
    _lib: libloading::Library,
    func: NativeEvalFn,
}

impl NativeFunction {
    /// Call the native function with the given environment.
    pub fn call(&self, env: &[RuntimeValue]) -> RuntimeResult<RuntimeValue> {
        // SAFETY: The function pointer is valid because `_lib` keeps the
        // shared library mapped. Both sides are compiled with the same rustc
        // and link against the same `transpiler-runtime` rlib, so the ABI
        // is compatible.
        unsafe { (self.func)(env) }
    }
}

/// Generate a complete, compilable Rust source file from a function body.
///
/// The output is a cdylib source that imports `transpiler_runtime` and exports
/// a `#[no_mangle]` entry point.
pub fn generate_cdylib_source(eval_body: &str) -> String {
    format!(
        r#"// Auto-generated by tla-rs native codegen
use transpiler_runtime::*;
use transpiler_runtime::helpers::BinOp;
use std::sync::Arc;
use std::collections::BTreeMap;

// Bounds placeholder — will be passed from host in Phase c.v
static BOUNDS: RuntimeCollectionBounds = RuntimeCollectionBounds {{
    max_seq_len: 1024,
    max_set_len: 1024,
    max_map_len: 1024,
}};

{eval_body}

#[no_mangle]
pub fn native_eval(env: &[RuntimeValue]) -> RuntimeResult<RuntimeValue> {{
    eval(env)
}}
"#,
        eval_body = eval_body
    )
}

/// Compile Rust source to a cdylib and load it.
///
/// # Arguments
/// * `rust_source` — Complete Rust source (from `generate_cdylib_source`)
/// * `runtime_rlib_path` — Path to the compiled `transpiler_runtime` rlib
/// * `runtime_deps_dir` — Path to the directory containing runtime's dependencies
///
/// # Returns
/// A `NativeFunction` wrapping the loaded `native_eval` symbol.
pub fn compile_and_load(
    rust_source: &str,
    runtime_rlib_path: &Path,
    runtime_deps_dir: &Path,
) -> TranspileResult<NativeFunction> {
    let tmp_dir = std::env::temp_dir().join(format!("tla_rs_native_{}", std::process::id()));
    std::fs::create_dir_all(&tmp_dir).map_err(|e| TranspileError::Config {
        message: format!("Failed to create temp dir: {}", e),
    })?;

    let src_path = tmp_dir.join("native_eval.rs");
    let lib_name = format!(
        "native_eval_{}",
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_nanos()
    );
    let out_path = tmp_dir.join(cdylib_filename(&lib_name));

    // Write source
    std::fs::write(&src_path, rust_source).map_err(|e| TranspileError::Config {
        message: format!("Failed to write source: {}", e),
    })?;

    // Compile with rustc
    let output = Command::new("rustc")
        .arg("--crate-type=cdylib")
        .arg("--edition=2021")
        .arg("-O") // optimize for speed
        .arg("-o")
        .arg(&out_path)
        .arg("--extern")
        .arg(format!(
            "transpiler_runtime={}",
            runtime_rlib_path.display()
        ))
        .arg("-L")
        .arg(format!("dependency={}", runtime_deps_dir.display()))
        .arg(&src_path)
        .output()
        .map_err(|e| TranspileError::Config {
            message: format!("Failed to invoke rustc: {}", e),
        })?;

    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        return Err(TranspileError::Config {
            message: format!("rustc compilation failed:\n{}", stderr),
        });
    }

    // Load the cdylib
    let lib = unsafe {
        libloading::Library::new(&out_path).map_err(|e| TranspileError::Config {
            message: format!("Failed to load cdylib: {}", e),
        })?
    };

    // Look up the entry point
    let func = unsafe {
        let sym: libloading::Symbol<NativeEvalFn> =
            lib.get(b"native_eval")
                .map_err(|e| TranspileError::Config {
                    message: format!("Failed to find native_eval symbol: {}", e),
                })?;
        // Transmute to a raw fn pointer that outlives the Symbol borrow
        std::mem::transmute::<
            libloading::Symbol<NativeEvalFn>,
            NativeEvalFn,
        >(sym)
    };

    Ok(NativeFunction { _lib: lib, func })
}

/// Find the pre-compiled runtime rlib path.
///
/// Searches for `libtranspiler_runtime.rlib` in common locations:
/// 1. Adjacent to the current executable's deps directory
/// 2. In the CARGO_TARGET_DIR/debug/deps
/// 3. In the workspace target/debug/deps
pub fn find_runtime_rlib(runtime_crate_dir: &Path) -> TranspileResult<(PathBuf, PathBuf)> {
    // Try building the runtime crate to get the rlib path
    let output = Command::new("cargo")
        .arg("build")
        .arg("--message-format=json")
        .current_dir(runtime_crate_dir)
        .output()
        .map_err(|e| TranspileError::Config {
            message: format!("Failed to build runtime crate: {}", e),
        })?;

    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        return Err(TranspileError::Config {
            message: format!("Runtime crate build failed:\n{}", stderr),
        });
    }

    // Parse cargo build output to find the rlib path
    let stdout = String::from_utf8_lossy(&output.stdout);
    for line in stdout.lines() {
        if let Ok(msg) = serde_json::from_str::<serde_json::Value>(line) {
            if msg.get("reason").and_then(|r| r.as_str()) == Some("compiler-artifact")
                && msg
                    .get("target")
                    .and_then(|t| t.get("name"))
                    .and_then(|n| n.as_str())
                    == Some("transpiler-runtime")
            {
                if let Some(filenames) = msg.get("filenames").and_then(|f| f.as_array()) {
                    for f in filenames {
                        if let Some(path_str) = f.as_str() {
                            if path_str.ends_with(".rlib") {
                                let rlib_path = PathBuf::from(path_str);
                                let deps_dir = rlib_path.parent().unwrap().to_path_buf();
                                return Ok((rlib_path, deps_dir));
                            }
                        }
                    }
                }
            }
        }
    }

    Err(TranspileError::Config {
        message: "Could not find transpiler-runtime rlib in cargo output".to_string(),
    })
}

/// Cache for natively compiled functions, keyed by expression pointer + env names.
///
/// Thread-safe: uses `Mutex<HashMap>` + `Arc<NativeFunction>` so it can be
/// shared across parallel BFS workers.
pub struct NativeCache {
    /// `None` = compilation failed (cached failure); `Some` = loaded function.
    cache: Mutex<NativeCacheMap>,
    runtime_rlib_path: PathBuf,
    runtime_deps_dir: PathBuf,
}

impl NativeCache {
    /// Create a new cache with pre-resolved runtime paths.
    pub fn new(runtime_rlib_path: PathBuf, runtime_deps_dir: PathBuf) -> Self {
        Self {
            cache: Mutex::new(HashMap::new()),
            runtime_rlib_path,
            runtime_deps_dir,
        }
    }

    /// Return the (rlib_path, deps_dir) pair for constructing a second cache
    /// with the same pre-built runtime (avoids a second `cargo build`).
    pub fn rlib_paths(&self) -> (PathBuf, PathBuf) {
        (
            self.runtime_rlib_path.clone(),
            self.runtime_deps_dir.clone(),
        )
    }

    /// Try to initialize by building the runtime crate.
    pub fn try_new(runtime_crate_dir: &Path) -> TranspileResult<Self> {
        let (rlib, deps) = find_runtime_rlib(runtime_crate_dir)?;
        Ok(Self::new(rlib, deps))
    }

    /// Get or compile a native function for the given expression.
    ///
    /// Returns `Some(Arc<NativeFunction>)` on success, `None` on failure.
    /// On compilation failure, caches the failure and returns `None`
    /// (graceful fallback to bytecode/AST).
    pub fn get_or_compile(
        &self,
        expr: &crate::ast::Expr,
        env_names: &[String],
        source_gen: impl FnOnce() -> Result<String, crate::modelcheck::native_codegen::CodegenError>,
    ) -> Option<Arc<NativeFunction>> {
        let key = (expr as *const _ as usize, env_names.to_vec());

        // Check cache first
        {
            let guard = self.cache.lock().unwrap();
            if let Some(entry) = guard.get(&key) {
                return entry.clone();
            }
        }

        // Generate source (outside lock to avoid holding it during compilation)
        let source = match source_gen() {
            Ok(body) => generate_cdylib_source(&body),
            Err(_) => {
                self.cache.lock().unwrap().insert(key, None);
                return None;
            }
        };

        // Compile and load (expensive — outside lock)
        let result = compile_and_load(&source, &self.runtime_rlib_path, &self.runtime_deps_dir);

        let entry = result.ok().map(Arc::new);
        let ret = entry.clone();
        self.cache.lock().unwrap().insert(key, entry);
        ret
    }
}

#[cfg(target_os = "linux")]
fn cdylib_filename(name: &str) -> String {
    format!("lib{}.so", name)
}

#[cfg(target_os = "macos")]
fn cdylib_filename(name: &str) -> String {
    format!("lib{}.dylib", name)
}

#[cfg(target_os = "windows")]
fn cdylib_filename(name: &str) -> String {
    format!("{}.dll", name)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_generate_cdylib_source_structure() {
        let body = r#"fn eval(env: &[RuntimeValue]) -> RuntimeResult<RuntimeValue> {
    Ok(RuntimeValue::Bool(true))
}"#;
        let source = generate_cdylib_source(body);
        assert!(source.contains("use transpiler_runtime::*;"));
        assert!(source.contains("use transpiler_runtime::helpers::BinOp;"));
        assert!(source.contains("#[no_mangle]"));
        assert!(source.contains("pub fn native_eval"));
        assert!(source.contains("fn eval(env:"));
        assert!(source.contains("RuntimeCollectionBounds"));
    }

    #[test]
    fn test_cdylib_filename() {
        #[cfg(target_os = "linux")]
        assert_eq!(cdylib_filename("test"), "libtest.so");
        #[cfg(target_os = "macos")]
        assert_eq!(cdylib_filename("test"), "libtest.dylib");
    }

    #[test]
    fn test_native_cache_rlib_paths_roundtrip() {
        let rlib = PathBuf::from("/tmp/test.rlib");
        let deps = PathBuf::from("/tmp/deps");
        let cache = NativeCache::new(rlib.clone(), deps.clone());
        let (got_rlib, got_deps) = cache.rlib_paths();
        assert_eq!(got_rlib, rlib);
        assert_eq!(got_deps, deps);
    }

    #[test]
    fn test_native_cache_get_or_compile_caches_failure() {
        let cache = NativeCache::new(
            PathBuf::from("/nonexistent/test.rlib"),
            PathBuf::from("/nonexistent/deps"),
        );
        // Use a simple expression that would fail to compile (no rlib)
        let expr = crate::ast::Expr::Literal(crate::ast::Literal::Int(42));
        let env_names = vec![];
        // First call: should attempt compilation, fail, cache None
        let result1 = cache.get_or_compile(&expr, &env_names, || {
            Ok("fn eval(env: &[RuntimeValue]) -> RuntimeResult<RuntimeValue> { Ok(RuntimeValue::Int(42)) }".to_string())
        });
        assert!(result1.is_none(), "Should fail with nonexistent rlib");
        // Second call with same expr: should return cached None without re-calling source_gen
        let result2 = cache.get_or_compile(&expr, &env_names, || {
            panic!("source_gen should not be called for cached failure");
        });
        assert!(result2.is_none(), "Should return cached failure");
    }

    #[test]
    fn test_native_cache_is_send_sync() {
        fn assert_send_sync<T: Send + Sync>() {}
        assert_send_sync::<NativeCache>();
    }

    #[test]
    fn test_native_function_is_send_sync() {
        fn assert_send_sync<T: Send + Sync>() {}
        assert_send_sync::<NativeFunction>();
    }

    #[test]
    fn test_native_cache_concurrent_codegen_failure() {
        use std::sync::Arc as StdArc;
        let cache = StdArc::new(NativeCache::new(
            PathBuf::from("/nonexistent/test.rlib"),
            PathBuf::from("/nonexistent/deps"),
        ));
        let expr: &'static crate::ast::Expr = Box::leak(Box::new(crate::ast::Expr::Literal(
            crate::ast::Literal::Int(77),
        )));
        let handles: Vec<_> = (0..4)
            .map(|_| {
                let cache = StdArc::clone(&cache);
                std::thread::spawn(move || {
                    cache.get_or_compile(expr, &[], || {
                        Ok("fn eval(env: &[RuntimeValue]) -> RuntimeResult<RuntimeValue> { Ok(RuntimeValue::Int(77)) }".to_string())
                    })
                })
            })
            .collect();
        let results: Vec<_> = handles.into_iter().map(|h| h.join().unwrap()).collect();
        // All threads should get None (compilation fails with nonexistent rlib)
        for r in &results {
            assert!(r.is_none(), "Should fail with nonexistent rlib");
        }
    }

    #[test]
    fn test_native_cache_get_or_compile_codegen_failure_cached() {
        let cache = NativeCache::new(
            PathBuf::from("/nonexistent/test.rlib"),
            PathBuf::from("/nonexistent/deps"),
        );
        let expr = crate::ast::Expr::Literal(crate::ast::Literal::Int(1));
        let env_names = vec![];
        // source_gen returns Err → should cache None
        let result = cache.get_or_compile(&expr, &env_names, || {
            Err(crate::modelcheck::native_codegen::CodegenError {
                message: "unsupported".to_string(),
            })
        });
        assert!(result.is_none());
        // Second call: cached failure, source_gen not called
        let result2 = cache.get_or_compile(&expr, &env_names, || {
            panic!("should not be called");
        });
        assert!(result2.is_none());
    }
}
